contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function; caller is this contract (deployer of c)
    function run(uint256 burnAmount) public payable {
        require(true);
        // Read before-values
        address self = address(this);
        uint256 beforeTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeBalance = c.balanceOf(self); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotal = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterBalance = c.balanceOf(self); if (__ESBMC_reverted()) return;

        // If the call did not revert, it must have reduced totalSupply and caller balance by exactly burnAmount
        // If it reverted, no change is required. This captures the owner-only requirement because only owner can burn.
        assert(reverted || (afterTotal + burnAmount == beforeTotal && afterBalance + burnAmount == beforeBalance));
    }

    receive() external payable { }
}

