import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 burnAmount) internal {
        vm.assume(true);
        address self = address(this);
        uint256 beforeTotal;
        try c.totalSupply() returns (uint256 __r) { beforeTotal = __r; } catch { return; }
        uint256 beforeBalance;
        try c.balanceOf(self) returns (uint256 __r) { beforeBalance = __r; } catch { return; }
        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotal;
        try c.totalSupply() returns (uint256 __r) { afterTotal = __r; } catch { return; }
        uint256 afterBalance;
        try c.balanceOf(self) returns (uint256 __r) { afterBalance = __r; } catch { return; }
        assertTrue(reverted || (afterTotal + burnAmount == beforeTotal && afterBalance + burnAmount == beforeBalance));
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

    receive() external payable { }
}
